// ① hex → bytes（零第三方依赖：Java 标准库 BigInteger）
function RG_decodeHex(hex){
  var s=String(hex||'');
  if(s.length===0) return new Uint8Array(0);
  if(s.length%2===1) s='0'+s;   // 奇数长度补前导零
  var bi=new Packages.java.math.BigInteger(s,16);
  var arr=bi.toByteArray();
