    var java = this.java;
    if (ident == null) ident = '段评';
    var rt = this.probe();
    if (rt == "panel") {
        var htmlContent = '';
        try {
            htmlContent = java.ajax(url);
        } catch (e) {}
        try {
        java.showBrowser(
            url,
            htmlContent,
            'window.java=java;',
            JSON.stringify({
                "expandedCornersRadius": 20,
                "dismissOnTouchOutside": true,
                "isDraggable": true,
                "shouldDimBackground": true,
