@js:(function(){
  var out='';
  var SEP=function(t){return '✦ ──── '+t+' ──── ✦';};
  try{
    var j=(JSON.parse(result).book)||{};
    if(!j.title&&!j.description){return '⚠️ 未获取到书籍信息，请先在书源菜单点「登录」。';}
    var _bid=String(j.id||'');
    var _base=String(source.bookSourceUrl||'').replace(/#.*$/,'').replace(/\/+$/,'');
    var _u=null;
    try{var _pj=JSON.parse(java.ajax(_base+'/eapi/user/profile'));_u=(_pj&&_pj.user)||null;}catch(e){}
    var _an=_u?String(_u.name||_u.email||''):'';
    var _used=_u?Number(_u.downloads_today):NaN;
    var _lim=_u?Number(_u.downloads_limit):NaN;
    var _dbg={b:_bid,a:_an,cur:(isNaN(_used)?null:_used),prev:null,to:null,hit:0};
    try{
      if(_an&&!isNaN(_used)){
        var _lq={};
        try{_lq=JSON.parse(String(cache.get('zl_lq')||'')||'{}')||{};}catch(e){_lq={};}
        if(_lq&&_lq.a===_an&&_lq.q!=null&&_lq.b){
          var _pn=Number(_lq.q);
          _dbg.prev=_pn;_dbg.to=String(_lq.b);
          if(!isNaN(_pn)&&_used>_pn){
            cache.put('zl_dlv_'+String(_lq.b),String(_lq.t||Date.now()),0);
            try{java.log('Z-Library 判定下载: 书#'+_lq.b+' 已用 '+_pn+'→'+_used+' 归属书#'+_lq.b);}catch(e){}
            _dbg.hit=1;
          }
        }
        cache.put('zl_lq',JSON.stringify({a:_an,b:_bid,q:_used,t:Date.now()}),0);
      }
    }catch(e){}
    try{
      var _log=[];
      try{_log=JSON.parse(String(cache.get('zl_log')||'')||'[]')||[];}catch(e){_log=[];}
      if(!_log||_log.length==null){_log=[];}
      _log.push(_dbg);
      while(_log.length>5){_log.shift();}
      cache.put('zl_log',JSON.stringify(_log),0);
    }catch(e){}
    try{cache.put('zl_dbg',JSON.stringify(_dbg),0);}catch(e){}
    try{
      var _dT=parseInt(String(cache.get('zl_dlv_'+_bid)||''),10);
      if(!isNaN(_dT)&&_dT>0){
        var _rdt=new Date(_dT);
        out+='✅ 本机记录：这本下载过（'+(_rdt.getMonth()+1)+'月'+_rdt.getDate()+'日 '+('0'+_rdt.getHours()).slice(-2)+':'+('0'+_rdt.getMinutes()).slice(-2)+'）\n\n';
      }
    }catch(e){}
    var _tip='';
    if(!isNaN(_used)&&!isNaN(_lim)&&_lim>0&&_used>=_lim){
      var _t='';
      try{
        var _now=Date.now();var _bj=new Date(_now+8*3600000);
        var _reset=Date.UTC(_bj.getUTCFullYear(),_bj.getUTCMonth(),_bj.getUTCDate(),5,0,0)-8*3600000;
        if(_now>=_reset){_reset+=86400000;}
        var _m=Math.round((_reset-_now)/60000);if(_m<0){_m=0;}
        _t='，'+Math.floor(_m/60)+'h'+(_m%60)+'m 后重置';
      }catch(e){}
      _tip='⚠️ 今日下载次数已用完（'+_used+'/'+_lim+'）'+_t+'\n　额度每天北京时间 05:00 更新';
    }else if(_an&&!isNaN(_used)&&!isNaN(_lim)&&_lim>0){
      _tip='💾 下载本书：点【加入书架】或【阅读】任意一个\n　账号 '+_an+' · 今日还剩 '+(_lim-_used)+' 次\n　首次计 1 次 · 重复下不扣 · 下完在书架里搜书名';
    }else{
      _tip='💾 下载本书：点【加入书架】或【阅读】任意一个\n　首次计 1 次 · 重复下不扣 · 下完在书架里搜书名';
    }
    out+=_tip+'\n\n';
    var info=[];
    if(j.title){info.push('📖 书名：'+String(j.title));}
    if(j.author){info.push('👤 作者：'+String(j.author));}
    var _pub=[];
    if(j.publisher){_pub.push(String(j.publisher));}
    if(j.year){_pub.push(String(j.year)+'年');}
    if(_pub.length){info.push('🏢 出版：'+_pub.join(' · '));}
    if(j.language){info.push('🌐 语言：'+String(j.language));}
    var _fmt=[];
    var ex=String(j.extension||'').toUpperCase();
    if(ex){_fmt.push(ex);}
    if(j.filesizeString){_fmt.push(String(j.filesizeString));}
    if(j.pages){_fmt.push(String(j.pages)+' 页');}
    if(_fmt.length){info.push('📄 格式：'+_fmt.join(' · '));}
    var _sc=[];
    if(j.qualityScore!=null){_sc.push('⭐ '+String(j.qualityScore)+' / 5');}
    if(j.interestScore!=null){_sc.push('🔥 热度 '+String(j.interestScore));}
    if(_sc.length){info.push(_sc.join('　'));}
    var _ids=[];
    if(j.identifier){_ids.push('🔖 ISBN '+String(j.identifier));}
    if(j.series){_ids.push('📚 系列 '+String(j.series));}
    if(j.edition){_ids.push('📕 版本 '+String(j.edition));}
    if(_ids.length){info.push(_ids.join('　'));}
    if(info.length){out+=SEP('书籍信息')+'\n'+info.join('\n')+'\n\n';}
    var d=String(j.description||'').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&#x27;/g,"'").replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
    if(d){
      if(d.length>200){
        var _cut=d.substring(0,200),_last=-1;
        for(var _pi=0;_pi<_cut.length;_pi++){var _ch=_cut.charAt(_pi);if(_ch==='。'||_ch==='！'||_ch==='？'||_ch==='!'||_ch==='?'||_ch==='.'){_last=_pi;}}
        if(_last>=120){_cut=_cut.substring(0,_last+1);}else{var _sp=_cut.lastIndexOf(' ');if(_sp>120){_cut=_cut.substring(0,_sp);}}
        d=_cut+'…';
      }
      out+=SEP('内容简介')+'\n'+d+'\n\n';
    }
    var LIMIT=15;
    try{
      var _c=[];
      try{var _bv=book.getVariable('custom');if(_bv!=null){_c.push(String(_bv));}}catch(e){}
      try{var _sv=source.getVariable();if(_sv!=null){_c.push(String(_sv));}}catch(e){}
      for(var _i=0;_i<_c.length;_i++){var _mm=String(_c[_i]).match(/\d+/);if(_mm){var _n=parseInt(_mm[0],10);if(!isNaN(_n)){LIMIT=_n;break;}}}
    }catch(e){}
    if(LIMIT>0){
      try{
        var _pull=Math.max(100,LIMIT);
        var cj=JSON.parse(java.ajax(_base+'/papi/comments/book/'+j.id+'/0?limit='+_pull));
        var arr=(cj&&cj.comments)||[];
        var _rs=(cj&&cj.reactionsInfo&&cj.reactionsInfo.reactions)||[];
        var _lm={};
        for(var _ri=0;_ri<_rs.length;_ri++){_lm[String(_rs[_ri].item_id)]=Number(_rs[_ri].count)||0;}
        var _ca=[];
        for(var _ci2=0;_ci2<arr.length;_ci2++){
          var _cc=arr[_ci2]||{};
          var _tx=String(_cc.text||'').replace(/\s+/g,' ').trim();
          if(!_tx){continue;}
          _ca.push({i:_ci2,t:_tx,dt:_cc.dateRelative?String(_cc.dateRelative):'',lk:_lm[String(_cc.id)]||0});
        }
        _ca.sort(function(a,b){return (b.lk-a.lk)||(a.i-b.i);});
        var lines=[];
        for(var _li=0;_li<_ca.length&&lines.length<LIMIT;_li++){
          var _it=_ca[_li];
          lines.push((lines.length+1)+'. '+(_it.dt?('['+_it.dt+'] '):'')+_it.t);
        }
        out+=SEP('读者评论 · 按热度')+'\n'+(lines.length?lines.join('\n'):'（暂无评论）');
      }catch(e2){ out+=SEP('读者评论')+'\n（获取失败）'; }
    }
  }catch(e){}
  return out;
})()

