// ==================== Base64 解码（支持 = padding） ====================
function base64Decode(str) {
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    var bytes = [];
    var i = 0;
    str = str.replace(/[^A-Za-z0-9+/=]/g, '');
    while (i < str.length) {
        var c1 = chars.indexOf(str.charAt(i++));
        var c2 = chars.indexOf(str.charAt(i++));
        var c3 = chars.indexOf(str.charAt(i++));
        var c4 = chars.indexOf(str.charAt(i++));
        if (c1 < 0) break;
        var byte1 = (c1 << 2) | (c2 >> 4);
        bytes.push(byte1);
        if (c3 >= 0) {
            var byte2 = ((c2 & 15) << 4) | (c3 >> 2);
            bytes.push(byte2);
        }
        if (c4 >= 0) {
            var byte3 = ((c3 & 3) << 6) | c4;
            bytes.push(byte3);
        }
    }
    return bytes;
}

// ==================== UTF-8 解码 ====================
function utf8Decode(bytes) {
    var str = '';
    for (var i = 0; i < bytes.length; i++) {
        var b = bytes[i];
        if (b < 0x80) {
            str += String.fromCharCode(b);
        } else if (b < 0xE0) {
            str += String.fromCharCode(((b & 0x1F) << 6) | (bytes[++i] & 0x3F));
        } else if (b < 0xF0) {
            str += String.fromCharCode(((b & 0x0F) << 12) | ((bytes[++i] & 0x3F) << 6) | (bytes[++i] & 0x3F));
        } else {
            var cp = ((b & 0x07) << 18) | ((bytes[++i] & 0x3F) << 12) | ((bytes[++i] & 0x3F) << 6) | (bytes[++i] & 0x3F);
            cp -= 0x10000;
            str += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
        }
    }
    return str;
}

// ==================== 解密函数 ====================
function decrypt(encrypted) {
    var PREFIX = 'qM9';
    var SUFFIX = 'Z7';
    var VX = 'Vx';
    var PL0 = 'pL0';
    var MAP1 = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var MAP2 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

    if (typeof encrypted !== 'string' || encrypted.indexOf(PREFIX) !== 0 || encrypted.slice(-SUFFIX.length) !== SUFFIX) {
        throw new Error('x1');
    }

    var s = encrypted.slice(PREFIX.length, encrypted.length - SUFFIX.length);
    var len = s.length - VX.length - PL0.length;
    if (len <= 0) throw new Error('x2');

    var n1 = Math.floor(len / 3);
    var n2 = Math.floor((len - n1) / 2);
    var n3 = len - n1 - n2;

    var part1 = s.slice(0, n2);
    var check1 = s.slice(n2, n2 + VX.length);
    var part2 = s.slice(n2 + VX.length, n2 + VX.length + n3);
    var check2 = s.slice(n2 + VX.length + n3, n2 + VX.length + n3 + PL0.length);
    var part3 = s.slice(n2 + VX.length + n3 + PL0.length);

    if (check1 !== VX || check2 !== PL0 || part3.length !== n1) {
        throw new Error('x3');
    }

    var combined = part3 + part1 + part2;

    // 每 7 个字符一组，奇数索引组反转
    var reversed = '';
    var groupSize = 7;
    for (var i = 0, groupIdx = 0; i < combined.length; i += groupSize, groupIdx++) {
        var group = combined.slice(i, i + groupSize);
        if (groupIdx % 2 === 0) {
            reversed += group;
        } else {
            reversed += group.split('').reverse().join('');
        }
    }

    // 字符映射
    var mapped = '';
    for (var j = 0; j < reversed.length; j++) {
        var ch = reversed.charAt(j);
        var idx = MAP1.indexOf(ch);
        if (idx === -1) throw new Error('x0: ' + ch);
        mapped += MAP2.charAt(idx);
    }

    // Base64 补 padding
    var padded = mapped;
    var rem = mapped.length % 4;
    if (rem) {
        for (var k = 0; k < 4 - rem; k++) padded += '=';
    }

    var base64Str = padded.replace(/-/g, '+').replace(/_/g, '/');
    var bytes = base64Decode(base64Str);
    var jsonStr = utf8Decode(bytes);

    return JSON.parse(jsonStr);
}

// ==================== 主流程 ====================
var chapterHtml = java.ajax(baseUrl);
var chapterDoc = org.jsoup.Jsoup.parse(chapterHtml);
var chapContent = chapterDoc.select("#chapcontent").first();

if (!chapContent) {
    result = "<p>未找到 #chapcontent</p>";
} else {
    var apiHid = chapContent.attr("data-api-hid");
    var apiBase = chapContent.attr("data-api-base-url-line1") || "https://hipapi1.s3file.top";
    var imgBase = chapContent.attr("data-chapter-img-base-line1") || "https://hip-tx-1.s3imgs.top";

    var apiUrl = apiBase + "/v2/chapter?hid=" + encodeURIComponent(apiHid);
    var apiResp = java.ajax(apiUrl);
    var apiJson = JSON.parse(apiResp);
    var encrypted = apiJson.data.images;

    var images;
    if (typeof encrypted === 'string') {
        images = decrypt(encrypted);
    } else if (Array.isArray(encrypted)) {
        images = encrypted;
    } else {
        images = [];
    }

    var resultList = [];
    for (var m = 0; m < images.length; m++) {
        var src = images[m];
        if (src.indexOf("http") === 0) {
            resultList.push(src);
        } else {
            resultList.push(imgBase + src);
        }
    }

    // 生成 <img> 标签
    var html = '';
    for (var m = 0; m < resultList.length; m++) {
        html += '<img src="' + resultList[m] + '">';
    }
    result = html;
}

